INSERT INTO public.recipes (id, nom, description, saison, mois, mois_numero, semaine, jour, tag, categorie, theme_special, portions, estimated_time, difficulty, image_url, ingredients, instructions, astuce, cuisson_micro_ondes, sans_four, source, source_pdf, source_page, dietary_tags, main_ingredients, equipment, canonical_ingredients_status)
VALUES
  ('city-cafe-brochettes-de-saumon-et-saint-jacques-sauce-gremolata', 'Brochettes de saumon et Saint-Jacques, sauce gremolata', 'Brochettes de saumon et Saint-Jacques, sauce gremolata préparé simplement à la maison, avec des quantités équilibrées et une cuisson adaptée aux ingrédients.', 'été', 'juin', 6, null, null, 'déjeuner/dîner', 'salé', null, '2 personnes', 35, 'facile', 'https://images.pexels.com/photos/39193006/pexels-photo-39193006.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '[{"name":"Saumon","quantity":"300","unit":"g","canonical":true,"category":"Viandes, poissons et protéines"},{"name":"Huile d''olive","quantity":"1","unit":"c. à soupe","canonical":true,"category":"Épicerie, condiments et produits sucrés"},{"name":"Citrons","quantity":"1","unit":"pièces","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Persil","quantity":"1","unit":"c. à soupe","canonical":true,"category":"Épices et herbes aromatiques"},{"name":"Sel et poivre","quantity":"1","unit":"c. à soupe","canonical":true,"category":"Épicerie, condiments et produits sucrés"}]'::jsonb, '["Sécher le poisson et préparer les garnitures saumon; préchauffer le four à 190 °C si la cuisson est au four.","Cuire les accompagnements séparément: démarrer les pommes de terre ou les céréales dans une casserole d’eau salée.","Saisir le poisson dans une poêle huilée 2 à 3 min par face selon l’épaisseur, ou le cuire au four 10 à 15 min jusqu’à ce que sa chair soit opaque et se détache.","Préparer la sauce avec les aromates et le citron, puis servir immédiatement avec le poisson et l’accompagnement."]'::jsonb, 'Préparez et pesez les ingrédients avant de commencer; ajustez le temps de cuisson à la taille réelle des morceaux et vérifiez la cuisson avant de servir.', false, true, 'broco-chou', null, null, array['poisson']::text[], array['saumon']::text[], array['casserole', 'poêle', 'couteau', 'planche à découper']::text[], 'verified'),
  ('city-cafe-sebaste-a-la-marseillaise-citron-caramelise-et-fenouil', 'Sébaste à la marseillaise, citron caramélisé et fenouil', 'Sébaste à la marseillaise, citron caramélisé et fenouil préparé simplement à la maison, avec des quantités équilibrées et une cuisson adaptée aux ingrédients.', 'été', 'juin', 6, null, null, 'déjeuner/dîner', 'salé', null, '2 personnes', 40, 'facile', 'https://images.pexels.com/photos/11091826/pexels-photo-11091826.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '[{"name":"Sébaste","quantity":"300","unit":"g","canonical":true,"category":"Viandes, poissons et protéines"},{"name":"Fenouil","quantity":"150","unit":"g","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Citrons","quantity":"1","unit":"pièces","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Huile d''olive","quantity":"1","unit":"c. à soupe","canonical":true,"category":"Épicerie, condiments et produits sucrés"},{"name":"Persil","quantity":"1","unit":"c. à soupe","canonical":true,"category":"Épices et herbes aromatiques"},{"name":"Sel et poivre","quantity":"1","unit":"c. à soupe","canonical":true,"category":"Épicerie, condiments et produits sucrés"}]'::jsonb, '["Sécher le poisson et préparer les garnitures sébaste, fenouil, citrons; préchauffer le four à 190 °C si la cuisson est au four.","Cuire les accompagnements séparément: démarrer les pommes de terre ou les céréales dans une casserole d’eau salée.","Saisir le poisson dans une poêle huilée 2 à 3 min par face selon l’épaisseur, ou le cuire au four 10 à 15 min jusqu’à ce que sa chair soit opaque et se détache.","Préparer la sauce avec les aromates et le citron, puis servir immédiatement avec le poisson et l’accompagnement."]'::jsonb, 'Préparez et pesez les ingrédients avant de commencer; ajustez le temps de cuisson à la taille réelle des morceaux et vérifiez la cuisson avant de servir.', false, true, 'broco-chou', null, null, array['poisson']::text[], array['sébaste', 'fenouil', 'citrons']::text[], array['casserole', 'poêle', 'couteau', 'planche à découper']::text[], 'verified'),
  ('city-cafe-joues-de-lotte-aux-deux-citrons-et-capres', 'Joues de lotte aux deux citrons et câpres', 'Joues de lotte aux deux citrons et câpres préparé simplement à la maison, avec des quantités équilibrées et une cuisson adaptée aux ingrédients.', 'printemps', 'avril', 4, null, null, 'déjeuner/dîner', 'salé', null, '2 personnes', 35, 'facile', 'https://images.pexels.com/photos/27039902/pexels-photo-27039902.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '[{"name":"Lotte","quantity":"300","unit":"g","canonical":true,"category":"Viandes, poissons et protéines"},{"name":"Câpres","quantity":"150","unit":"g","canonical":true,"category":"Épicerie, condiments et produits sucrés"},{"name":"Oignons","quantity":"1","unit":"pièces","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Carottes","quantity":"1","unit":"pièces","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Ail","quantity":"1","unit":"pièces","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Bouillon","quantity":"150","unit":"g","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Thym","quantity":"1","unit":"c. à soupe","canonical":true,"category":"Épices et herbes aromatiques"},{"name":"Sel et poivre","quantity":"1","unit":"c. à soupe","canonical":true,"category":"Épicerie, condiments et produits sucrés"}]'::jsonb, '["Éplucher et couper les oignons et les carottes en morceaux réguliers; sécher et assaisonner la viande si le plat en contient. Faire chauffer l’huile dans une cocotte.","Faire dorer la viande par petites quantités, puis ajouter oignons, carottes et ail et cuire 4 minutes. Pour une version végétarienne, faire simplement revenir les légumes et les légumineuses.","Ajouter le bouillon et les aromates, couvrir et mijoter doucement jusqu’à ce que les ingrédients soient tendres (30 à 90 minutes selon le plat); remuer et ajouter un peu d’eau si nécessaire.","Cuire l’accompagnement séparément, goûter la sauce, rectifier l’assaisonnement et servir chaud."]'::jsonb, 'Préparez et pesez les ingrédients avant de commencer; ajustez le temps de cuisson à la taille réelle des morceaux et vérifiez la cuisson avant de servir.', false, true, 'broco-chou', null, null, array['poisson']::text[], array['lotte', 'câpres']::text[], array['casserole', 'poêle', 'couteau', 'planche à découper']::text[], 'verified'),
  ('city-cafe-cabillaud-au-panko-et-mayonnaise-au-wasabi', 'Cabillaud au panko et mayonnaise au wasabi', 'Cabillaud au panko et mayonnaise au wasabi préparé simplement à la maison, avec des quantités équilibrées et une cuisson adaptée aux ingrédients.', 'été', 'juin', 6, null, null, 'déjeuner/dîner', 'salé', null, '2 personnes', 35, 'facile', 'https://images.pexels.com/photos/38995738/pexels-photo-38995738.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '[{"name":"Cabillaud","quantity":"300","unit":"g","canonical":true,"category":"Viandes, poissons et protéines"},{"name":"Huile d''olive","quantity":"1","unit":"c. à soupe","canonical":true,"category":"Épicerie, condiments et produits sucrés"},{"name":"Citrons","quantity":"1","unit":"pièces","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Persil","quantity":"1","unit":"c. à soupe","canonical":true,"category":"Épices et herbes aromatiques"},{"name":"Sel et poivre","quantity":"1","unit":"c. à soupe","canonical":true,"category":"Épicerie, condiments et produits sucrés"}]'::jsonb, '["Sécher le poisson et préparer les garnitures cabillaud; préchauffer le four à 190 °C si la cuisson est au four.","Cuire les accompagnements séparément: démarrer les pommes de terre ou les céréales dans une casserole d’eau salée.","Saisir le poisson dans une poêle huilée 2 à 3 min par face selon l’épaisseur, ou le cuire au four 10 à 15 min jusqu’à ce que sa chair soit opaque et se détache.","Préparer la sauce avec les aromates et le citron, puis servir immédiatement avec le poisson et l’accompagnement."]'::jsonb, 'Préparez et pesez les ingrédients avant de commencer; ajustez le temps de cuisson à la taille réelle des morceaux et vérifiez la cuisson avant de servir.', false, true, 'broco-chou', null, null, array['poisson']::text[], array['cabillaud']::text[], array['casserole', 'poêle', 'couteau', 'planche à découper']::text[], 'verified'),
  ('city-cafe-parmentier-de-poisson-a-la-patate-douce', 'Parmentier de poisson à la patate douce', 'Parmentier de poisson à la patate douce préparé simplement à la maison, avec des quantités équilibrées et une cuisson adaptée aux ingrédients.', 'hiver', 'janvier', 1, null, null, 'déjeuner/dîner', 'salé', null, '4 personnes', 65, 'facile', 'https://images.pexels.com/photos/24289143/pexels-photo-24289143.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '[{"name":"Poisson blanc","quantity":"600","unit":"g","canonical":true,"category":"Viandes, poissons et protéines"},{"name":"Pommes de terre","quantity":"2","unit":"pièces","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Œufs","quantity":"4","unit":"pièces","canonical":true,"category":"Crèmerie et produits laitiers"},{"name":"Fromage frais","quantity":"120","unit":"g","canonical":true,"category":"Crèmerie et produits laitiers"},{"name":"Sel et poivre","quantity":"1","unit":"c. à soupe","canonical":true,"category":"Épicerie, condiments et produits sucrés"}]'::jsonb, '["Préchauffer le four à 190 °C. Préparer la garniture poisson blanc et cuire au préalable les légumes humides dans une poêle pour évacuer leur eau.","Foncer le moule ou la plaque avec la pâte; piquer le fond. Mélanger les œufs, la crème et le fromage, puis assaisonner.","Répartir la garniture, verser l’appareil ou la sauce et enfourner 30 à 40 minutes jusqu’à ce que la pâte soit dorée et le centre pris.","Laisser reposer 8 minutes avant de couper; accompagner de la salade ou des herbes prévues."]'::jsonb, 'Préparez et pesez les ingrédients avant de commencer; ajustez le temps de cuisson à la taille réelle des morceaux et vérifiez la cuisson avant de servir.', false, false, 'broco-chou', null, null, array['poisson']::text[], array['poisson blanc']::text[], array['four', 'saladier', 'couteau', 'planche à découper']::text[], 'verified'),
  ('city-cafe-lieu-noir-en-croute-de-noisette-et-pistou-provencal', 'Lieu noir en croûte de noisette et pistou provençal', 'Lieu noir en croûte de noisette et pistou provençal préparé simplement à la maison, avec des quantités équilibrées et une cuisson adaptée aux ingrédients.', 'été', 'juin', 6, null, null, 'déjeuner/dîner', 'salé', null, '2 personnes', 35, 'facile', 'https://images.pexels.com/photos/35617863/pexels-photo-35617863.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '[{"name":"Lieu noir","quantity":"300","unit":"g","canonical":true,"category":"Viandes, poissons et protéines"},{"name":"Noisettes","quantity":"150","unit":"g","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Oignons","quantity":"1","unit":"pièces","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Ail","quantity":"1","unit":"pièces","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Huile d''olive","quantity":"1","unit":"c. à soupe","canonical":true,"category":"Épicerie, condiments et produits sucrés"},{"name":"Sel et poivre","quantity":"1","unit":"c. à soupe","canonical":true,"category":"Épicerie, condiments et produits sucrés"}]'::jsonb, '["Préparer et couper les légumes lieu noir, noisettes en morceaux réguliers. Préchauffer le four à 200 °C si la recette prévoit une cuisson rôtie.","Faire revenir les aromates dans une casserole ou une grande poêle avec l’huile, puis ajouter les légumes et les légumineuses.","Ajouter un fond d’eau ou de bouillon, couvrir et cuire 15 à 25 minutes jusqu’à tendreté; mélanger régulièrement et compléter le liquide si nécessaire.","Assaisonner, ajouter les herbes et le fromage prévus, puis servir avec l’accompagnement indiqué."]'::jsonb, 'Préparez et pesez les ingrédients avant de commencer; ajustez le temps de cuisson à la taille réelle des morceaux et vérifiez la cuisson avant de servir.', false, true, 'broco-chou', null, null, array['poisson']::text[], array['lieu noir', 'noisettes']::text[], array['casserole', 'poêle', 'couteau', 'planche à découper']::text[], 'verified'),
  ('city-cafe-fletan-en-papillote-d-ete', 'Flétan en papillote d’été', 'Flétan en papillote d’été préparé simplement à la maison, avec des quantités équilibrées et une cuisson adaptée aux ingrédients.', 'été', 'juillet', 7, null, null, 'déjeuner/dîner', 'salé', null, '2 personnes', 30, 'très facile', null, '[{"name":"Flétan","quantity":"300","unit":"g","canonical":true,"category":"Viandes, poissons et protéines"},{"name":"Oignons","quantity":"1","unit":"pièces","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Ail","quantity":"1","unit":"pièces","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Huile d''olive","quantity":"1","unit":"c. à soupe","canonical":true,"category":"Épicerie, condiments et produits sucrés"},{"name":"Sel et poivre","quantity":"1","unit":"c. à soupe","canonical":true,"category":"Épicerie, condiments et produits sucrés"}]'::jsonb, '["Préparer et couper les légumes flétan en morceaux réguliers. Préchauffer le four à 200 °C si la recette prévoit une cuisson rôtie.","Faire revenir les aromates dans une casserole ou une grande poêle avec l’huile, puis ajouter les légumes et les légumineuses.","Ajouter un fond d’eau ou de bouillon, couvrir et cuire 15 à 25 minutes jusqu’à tendreté; mélanger régulièrement et compléter le liquide si nécessaire.","Assaisonner, ajouter les herbes et le fromage prévus, puis servir avec l’accompagnement indiqué."]'::jsonb, 'Préparez et pesez les ingrédients avant de commencer; ajustez le temps de cuisson à la taille réelle des morceaux et vérifiez la cuisson avant de servir.', false, true, 'broco-chou', null, null, array['poisson']::text[], array['flétan']::text[], array['casserole', 'poêle', 'couteau', 'planche à découper']::text[], 'verified'),
  ('city-cafe-filets-de-perche-au-beurre-citron-basilic-et-pommes-frites', 'Filets de perche au beurre citron-basilic et pommes frites', 'Filets de perche au beurre citron-basilic et pommes frites préparé simplement à la maison, avec des quantités équilibrées et une cuisson adaptée aux ingrédients.', 'été', 'juin', 6, null, null, 'déjeuner/dîner', 'salé', null, '2 personnes', 45, 'facile', null, '[{"name":"Beurre","quantity":"60","unit":"g","canonical":true,"category":"Crèmerie et produits laitiers"},{"name":"Perche","quantity":"300","unit":"g","canonical":true,"category":"Viandes, poissons et protéines"},{"name":"Citrons","quantity":"1","unit":"pièces","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Basilic","quantity":"150","unit":"g","canonical":true,"category":"Épices et herbes aromatiques"},{"name":"Huile d''olive","quantity":"1","unit":"c. à soupe","canonical":true,"category":"Épicerie, condiments et produits sucrés"},{"name":"Persil","quantity":"1","unit":"c. à soupe","canonical":true,"category":"Épices et herbes aromatiques"},{"name":"Sel et poivre","quantity":"1","unit":"c. à soupe","canonical":true,"category":"Épicerie, condiments et produits sucrés"}]'::jsonb, '["Sécher le poisson et préparer les garnitures beurre, perche, citrons; préchauffer le four à 190 °C si la cuisson est au four.","Cuire les accompagnements séparément: démarrer les pommes de terre ou les céréales dans une casserole d’eau salée.","Saisir le poisson dans une poêle huilée 2 à 3 min par face selon l’épaisseur, ou le cuire au four 10 à 15 min jusqu’à ce que sa chair soit opaque et se détache.","Préparer la sauce avec les aromates et le citron, puis servir immédiatement avec le poisson et l’accompagnement."]'::jsonb, 'Préparez et pesez les ingrédients avant de commencer; ajustez le temps de cuisson à la taille réelle des morceaux et vérifiez la cuisson avant de servir.', false, true, 'broco-chou', null, null, array['poisson']::text[], array['beurre', 'perche', 'ci