  ('city-cafe-ceviche-d-eglefin-aux-agrumes-et-lait-de-coco', 'Ceviche d’églefin aux agrumes et lait de coco', 'Ceviche d’églefin aux agrumes et lait de coco préparé simplement à la maison, avec des quantités équilibrées et une cuisson adaptée aux ingrédients.', 'été', 'juin', 6, null, null, 'déjeuner/dîner', 'salé', null, '2 personnes', 30, 'très facile', 'https://images.pexels.com/photos/28490844/pexels-photo-28490844.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '[{"name":"Églefin","quantity":"300","unit":"g","canonical":true,"category":"Viandes, poissons et protéines"},{"name":"Oranges","quantity":"150","unit":"g","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Huile d''olive","quantity":"1","unit":"c. à soupe","canonical":true,"category":"Épicerie, condiments et produits sucrés"},{"name":"Citrons","quantity":"1","unit":"pièces","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Persil","quantity":"1","unit":"c. à soupe","canonical":true,"category":"Épices et herbes aromatiques"},{"name":"Sel et poivre","quantity":"1","unit":"c. à soupe","canonical":true,"category":"Épicerie, condiments et produits sucrés"}]'::jsonb, '["Choisir un poisson vendu pour consommation crue, le maintenir à 4 °C ou moins et le préparer avec du matériel propre; respecter les consignes du poissonnier concernant la congélation antiparasitaire.","Couper le poisson au couteau juste avant le repas. Mélanger avec agrumes, herbes et assaisonnement, puis réserver au réfrigérateur pendant la courte durée prévue par la recette.","Le jus de citron modifie la texture mais ne détruit pas de façon fiable les microbes ou parasites; ne pas servir à une personne enceinte, âgée ou immunodéprimée.","Servir très frais dès la préparation et jeter les restes; ne pas laisser le poisson cru à température ambiante."]'::jsonb, 'Préparez et pesez les ingrédients avant de commencer; ajustez le temps de cuisson à la taille réelle des morceaux et vérifiez la cuisson avant de servir.', false, true, 'broco-chou', null, null, array['poisson']::text[], array['églefin', 'oranges']::text[], array['casserole', 'poêle', 'couteau', 'planche à découper']::text[], 'verified'),
