  ('city-cafe-tartare-de-lieu-noir-avocat-tomate-et-coriandre', 'Tartare de lieu noir, avocat, tomate et coriandre', 'Tartare de lieu noir, avocat, tomate et coriandre préparé simplement à la maison, avec des quantités équilibrées et une cuisson adaptée aux ingrédients.', 'été', 'juin', 6, null, null, 'déjeuner/dîner', 'salé', null, '2 personnes', 25, 'très facile', 'https://images.pexels.com/photos/10296416/pexels-photo-10296416.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '[{"name":"Tomates","quantity":"150","unit":"g","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Avocats","quantity":"150","unit":"g","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Lieu noir","quantity":"300","unit":"g","canonical":true,"category":"Viandes, poissons et protéines"},{"name":"Coriandre","quantity":"150","unit":"g","canonical":true,"category":"Épices et herbes aromatiques"},{"name":"Oignons","quantity":"1","unit":"pièces","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Ail","quantity":"1","unit":"pièces","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Huile d''olive","quantity":"1","unit":"c. à soupe","canonical":true,"category":"Épicerie, condiments et produits sucrés"},{"name":"Sel et poivre","quantity":"1","unit":"c. à soupe","canonical":true,"category":"Épicerie, condiments et produits sucrés"}]'::jsonb, '["Préparer et couper les légumes tomates, avocats, lieu noir, coriandre en morceaux réguliers. Préchauffer le four à 200 °C si la recette prévoit une cuisson rôtie.","Faire revenir les aromates dans une casserole ou une grande poêle avec l’huile, puis ajouter les légumes et les légumineuses.","Ajouter un fond d’eau ou de bouillon, couvrir et cuire 15 à 25 minutes jusqu’à tendreté; mélanger régulièrement et compléter le liquide si nécessaire.","Assaisonner, ajouter les herbes et le fromage prévus, puis servir avec l’accompagnement indiqué."]'::jsonb, 'Préparez et pesez les ingrédients avant de commencer; ajustez le temps de cuisson à la taille réelle des morceaux et vérifiez la cuisson avant de servir.', false, true, 'broco-chou', null, null, array['poisson']::text[], array['tomates', 'avocats', 'lieu noir', 'coriandre']::text[], array['casserole', 'poêle', 'couteau', 'planche à découper']::text[], 'verified'),
