  ('city-cafe-lingue-bleue-gremolata-et-tagliatelles-fraiches', 'Lingue bleue gremolata et tagliatelles fraîches', 'Lingue bleue gremolata et tagliatelles fraîches préparé simplement à la maison, avec des quantités équilibrées et une cuisson adaptée aux ingrédients.', 'été', 'juin', 6, null, null, 'déjeuner/dîner', 'salé', null, '2 personnes', 35, 'facile', 'https://images.pexels.com/photos/18334680/pexels-photo-18334680.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '[{"name":"Pâtes","quantity":"160","unit":"g secs","canonical":true,"category":"Féculents, pains et céréales"},{"name":"Ail","quantity":"1","unit":"pièces","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Huile d''olive","quantity":"1","unit":"c. à soupe","canonical":true,"category":"Épicerie, condiments et produits sucrés"},{"name":"Sel et poivre","quantity":"1","unit":"c. à soupe","canonical":true,"category":"Épicerie, condiments et produits sucrés"},{"name":"Carottes","quantity":"1","unit":"pièces","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Courgettes","quantity":"1","unit":"pièces","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Pois chiches","quantity":"150","unit":"g","canonical":true,"category":"Fruits, légumes et légumineuses"}]'::jsonb, '["Porter une grande casserole d’eau salée à ébullition et cuire les pâtes selon leur emballage; réserver une louche d’eau de cuisson.","Pendant ce temps, préparer et couper les garnitures pâtes, ail, huile d’olive. Faire revenir les éléments aromatiques dans une poêle avec l’huile.","Ajouter les ingrédients principaux et cuire jusqu’à tendreté; incorporer la sauce ou le fromage prévu et détendre avec un peu d’eau de cuisson.","Mélanger avec les pâtes égouttées, rectifier l’assaisonnement et servir aussitôt avec la garniture restante."]'::jsonb, 'Préparez et pesez les ingrédients avant de commencer; ajustez le temps de cuisson à la taille réelle des morceaux et vérifiez la cuisson avant de servir.', false, true, 'broco-chou', null, null, array['poisson']::text[], array['pâtes', 'ail', 'huile d’olive']::text[], array['casserole', 'poêle', 'couteau', 'planche à découper']::text[], 'verified'),
