  ('city-cafe-supions-aux-pleurotes-et-beurre-persille', 'Supions aux pleurotes et beurre persillé', 'Supions aux pleurotes et beurre persillé préparé simplement à la maison, avec des quantités équilibrées et une cuisson adaptée aux ingrédients.', 'automne', 'octobre', 10, null, null, 'déjeuner/dîner', 'salé', null, '2 personnes', 30, 'très facile', 'https://images.pexels.com/photos/39444292/pexels-photo-39444292.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '[{"name":"Beurre","quantity":"60","unit":"g","canonical":true,"category":"Crèmerie et produits laitiers"},{"name":"Pleurotes","quantity":"150","unit":"g","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Oignons","quantity":"1","unit":"pièces","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Ail","quantity":"1","unit":"pièces","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Huile d''olive","quantity":"1","unit":"c. à soupe","canonical":true,"category":"Épicerie, condiments et produits sucrés"},{"name":"Sel et poivre","quantity":"1","unit":"c. à soupe","canonical":true,"category":"Épicerie, condiments et produits sucrés"}]'::jsonb, '["Préparer et couper les légumes beurre, pleurotes en morceaux réguliers. Préchauffer le four à 200 °C si la recette prévoit une cuisson rôtie.","Faire revenir les aromates dans une casserole ou une grande poêle avec l’huile, puis ajouter les légumes et les légumineuses.","Ajouter un fond d’eau ou de bouillon, couvrir et cuire 15 à 25 minutes jusqu’à tendreté; mélanger régulièrement et compléter le liquide si nécessaire.","Assaisonner, ajouter les herbes et le fromage prévus, puis servir avec l’accompagnement indiqué."]'::jsonb, 'Préparez et pesez les ingrédients avant de commencer; ajustez le temps de cuisson à la taille réelle des morceaux et vérifiez la cuisson avant de servir.', false, true, 'broco-chou', null, null, array['végétarien']::text[], array['beurre', 'pleurotes']::text[], array['casserole', 'poêle', 'couteau', 'planche à découper']::text[], 'verified'),
