-- City Café batch 09: recettes. Generated from city-cafe-recipes-batch-09.json.
BEGIN;

ON CONFLICT (name) DO NOTHING;

ON CONFLICT (id) DO UPDATE SET
  nom = EXCLUDED.nom,
  description = EXCLUDED.description,
  saison = EXCLUDED.saison,
  mois = EXCLUDED.mois,
  mois_numero = EXCLUDED.mois_numero,
  semaine = EXCLUDED.semaine,
  jour = EXCLUDED.jour,
  tag = EXCLUDED.tag,
  categorie = EXCLUDED.categorie,
  theme_special = EXCLUDED.theme_special,
  portions = EXCLUDED.portions,
  estimated_time = EXCLUDED.estimated_time,
  difficulty = EXCLUDED.difficulty,
  image_url = EXCLUDED.image_url,
  ingredients = EXCLUDED.ingredients,
  instructions = EXCLUDED.instructions,
  astuce = EXCLUDED.astuce,
  cuisson_micro_ondes = EXCLUDED.cuisson_micro_ondes,
  sans_four = EXCLUDED.sans_four,
  source = EXCLUDED.source,
  source_pdf = EXCLUDED.source_pdf,
  source_page = EXCLUDED.source_page,
  dietary_tags = EXCLUDED.dietary_tags,
  main_ingredients = EXCLUDED.main_ingredients,
  equipment = EXCLUDED.equipment,
  canonical_ingredients_status = EXCLUDED.canonical_ingredients_status;

-- Keep ingredient JSON category labels aligned with the canonical ingredient catalog.
UPDATE public.recipes AS recipe
SET ingredients = (
  SELECT jsonb_agg(jsonb_set(item.ingredient, '{category}', to_jsonb(canonical.category), true) ORDER BY item.ordinality)
  FROM jsonb_array_elements(recipe.ingredients) WITH ORDINALITY AS item(ingredient, ordinality)
  JOIN public.ingredients AS canonical ON canonical.name = item.ingredient->>'name'
)
WHERE recipe.id IN ('city-cafe-brochettes-de-saumon-et-saint-jacques-sauce-gremolata', 'city-cafe-sebaste-a-la-marseillaise-citron-caramelise-et-fenouil', 'city-cafe-joues-de-lotte-aux-deux-citrons-et-capres', 'city-cafe-cabillaud-au-panko-et-mayonnaise-au-wasabi', 'city-cafe-parmentier-de-poisson-a-la-patate-douce', 'city-cafe-lieu-noir-en-croute-de-noisette-et-pistou-provencal', 'city-cafe-fletan-en-papillote-d-ete', 'city-cafe-filets-de-perche-au-beurre-citron-basilic-et-pommes-frites', 'city-cafe-salade-cesar-aux-gambas-panees', 'city-cafe-truite-de-mer-au-four-laquage-aux-herbes', 'city-cafe-ceviche-d-eglefin-aux-agrumes-et-lait-de-coco', 'city-cafe-daurade-et-sauce-vierge-estivale', 'city-cafe-tartare-de-lieu-noir-avocat-tomate-et-coriandre', 'city-cafe-bar-roti-aux-herbes-de-provence-et-aioli', 'city-cafe-curry-de-crevettes-au-lait-de-coco-et-legumes-wok', 'city-cafe-tartines-aillees-au-sebaste-et-pesto', 'city-cafe-darne-de-saumon-a-l-oseille', 'city-cafe-calamaretti-facon-bord-de-mer-frites-et-salade', 'city-cafe-eglefin-meuniere-et-creme-aigrelette-au-citron-vert', 'city-cafe-poulpe-a-la-mediterraneenne-et-pommes-fondantes', 'city-cafe-tartare-de-saumon-creme-aigre-a-l-echalote-et-ciboulette', 'city-cafe-filet-de-daurade-aux-saveurs-estivales', 'city-cafe-carrelet-parfume-au-combava', 'city-cafe-accras-de-poisson-et-salade-de-pommes-de-terre-creole', 'city-cafe-daurade-snackee-beurre-rouge-et-citron-confit', 'city-cafe-ragout-de-poulpe-a-la-provencale', 'city-cafe-filets-de-perche-sauce-citron', 'city-cafe-lingue-bleue-gremolata-et-tagliatelles-fraiches', 'city-cafe-lotte-au-bouillon-asiatique-citronnelle-et-coriandre', 'city-cafe-rouille-de-sebaste-a-la-marseillaise', 'city-cafe-bouillabaisse-marseillaise', 'city-cafe-eglefin-aux-coquillages-et-tagliatelles-fraiches', 'city-cafe-aile-de-raie-a-la-grenobloise', 'city-cafe-quenelles-de-brochet-sauce-nantua', 'city-cafe-cabillaud-en-croute-de-parmesan-et-noisette', 'city-cafe-maigre-en-croute-de-lentilles-et-agrumes', 'city-cafe-supions-aux-pleurotes-et-beurre-persille', 'city-cafe-cannellonis-de-poissons-nobles-sauce-tomate-maison');

